    fn builds_gateway_ping_request() {
        let client = GatewayClient::new(config_fixture());

        let request = client.build_ping_request();

        assert_eq!(request.method, "GET");
        assert_eq!(request.path, "/api/orbit-agent/ping");
        assert_eq!(request.bearer_token.as_deref(), Some("dev-token-placeholder"));
        assert_eq!(request.body, None);
        assert_eq!(
            client.absolute_url(&request.path).expect("url should build"),
            "https://gateway.test/api/orbit-agent/ping"
        );
    }

    #[test]
    fn builds_slice_2_claim_request() {
        let client = GatewayClient::new(config_fixture());

        let request = client.build_claim_request();

        assert_eq!(request.method, "POST");
        assert_eq!(request.path, "/api/orbit-agent/jobs/claim");
        assert_eq!(request.bearer_token.as_deref(), Some("dev-token-placeholder"));
        assert_eq!(request.body, None);
    }

