                name: $name,
                tld: $tld,
                host: $host,
                wireguardAddress: $wireguardAddress,
                gatewayEndpoint: $gatewayEndpoint,
                sshUser: $user,
                user: $user,
                status: NodeStatus::Active,
                hostKey: $hostKey,
            ),
        );

        $this->measureBakeStep(
            $timingRole,
            'role-assignment',
            fn () => $this->upsertRoleAssignment($node->id, $role, $tld, $ingressNode),
