            return;
        }

        $freshNode = $node->fresh();
        $node = $freshNode instanceof Node ? $freshNode : $node;

        $nodeResult = $this->measureBakeStep(
            $timingRole,
            'setup-node',
            fn () => $nodeConverger->converge(
