                    ->where('node_id', $nodeId)
                    ->where('role', NodeRoleName::Ingress->value)
                    ->delete();
            }
        }

        NodeRoleAssignment::query()->updateOrCreate(
            [
                'node_id' => $nodeId,
                'role' => $role,
            ],
            [
                'status' => NodeRoleStatus::Active->value,
                'settings' => $settings,
                'last_error' => null,
                'converged_at' => now(),
            ],
